use std::collections::HashMap;

fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    assert!(n >= 2);

    // Map value -> earliest index where it occurred.
    // Scanning left-to-right and returning on first match ensures lexicographically smallest pair.
    let mut first_pos: HashMap<u32, usize> = HashMap::new();

    for j in 0..n {
        let x = nums[j];
        let need = target.wrapping_sub(x);

        if let Some(&i) = first_pos.get(&need) {
            // i is guaranteed < j (since it was inserted from earlier positions).
            return (i, j);
        }

        // Keep the earliest index for each value to minimize i (and then j).
        first_pos.entry(x).or_insert(j);
    }

    // Problem statement guarantees existence of a solution.
    unreachable!("A valid pair is guaranteed to exist by the problem assumptions");
}